import { performance, PerformanceObserver } from "node:perf_hooks";
function main(): void {
  const a = new PerformanceObserver((list) => { console.log("a", list.getEntries().map((e) => e.name)); });
  const b = new PerformanceObserver((list) => { console.log("b", list.getEntries().map((e) => e.name)); });
  a.observe({ entryTypes: ["mark"] });
  b.observe({ entryTypes: ["mark"] });
  performance.mark("x");
  setTimeout(() => { a.disconnect(); b.disconnect(); console.log("done"); }, 20);
}
